import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import './App.css';
import NavBar from './Navbar/Navbar';
import Home from './Home/home';


function App() {
  return (
    <Router>

       <NavBar/>
       <Routes>
        <Route path="/" exact Component={Home}/>
        </Routes>
    </Router>
  );
}

export default App;
